:root {
  --paper: #fffdf7;
  --ink: #24302d;
  --accent: #d75a45;
  --mint: #dce9df;
  --line: #24302d;
}

.repair-tag {
  width: 450px;
  overflow: hidden;
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 14px;
}

.tag-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: var(--accent);
  color: var(--paper);
}

.tag-header p {
  margin: 0;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.tag-header time {
  padding: 3px 7px;
  border: 1px solid var(--paper);
  border-radius: 5px;
  font-size: 11px;
  font-weight: 800;
}

.tag-body {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
}

.keycap {
  display: grid;
  width: 64px;
  height: 64px;
  margin: 0;
  place-items: center;
  background: var(--mint);
  border: 2px solid var(--line);
  border-radius: 10px;
  font-size: 28px;
}

.tag-copy h1 {
  margin: 0 0 3px;
  font-size: 20px;
  line-height: 1.1;
}

.tag-copy p {
  margin: 0 0 8px;
  color: var(--ink);
  font-size: 14px;
}

.tag-copy strong {
  color: var(--accent);
  font-size: 11px;
  letter-spacing: 0.07em;
}
